/**
 * The live-coding method applied to one problem, frame by frame: what you say
 * out loud, what the interviewer answers, what goes on the whiteboard and, once
 * you code, the line you are writing. The dry run at the end is generated by
 * running the real algorithm on the example.
 */

const STAGES = ['Entender', 'Aclarar', 'Ejemplos', 'Fuerza bruta', 'Optimizar', 'Codificar', 'Probar y analizar']

interface Trace {
  arrays: { caption: string; values: string[]; states: Partial<Record<number, CellState>>; pointers: Pointer[] }[]
  mapTitle: string
  map: [string, string][]
  hit?: string
  fresh?: string
}

interface Frame {
  stage: number
  clock: string
  say: string
  reply?: string
  board: string[]
  fresh: number
  code: number
  line?: number | number[]
  trace?: Trace
  note: string
  tone?: 'ok' | 'bad'
}

/** A scripted moment; `add` appends lines to the whiteboard. */
interface Beat {
  stage: number
  clock: string
  say: string
  reply?: string
  add?: string[]
  code?: number
  line?: number | number[]
  note: string
  tone?: 'ok' | 'bad'
}

function play(beats: Beat[], board: string[], codeLen: number): { frames: Frame[]; board: string[] } {
  const frames: Frame[] = []
  let b = [...board]
  for (const beat of beats) {
    const add = beat.add ?? []
    b = [...b, ...add]
    frames.push({
      stage: beat.stage,
      clock: beat.clock,
      say: beat.say,
      reply: beat.reply,
      board: b,
      fresh: add.length,
      code: beat.code ?? (beat.stage === 6 ? codeLen : 0),
      line: beat.line,
      note: beat.note,
      tone: beat.tone,
    })
  }
  return { frames, board: b }
}

/* ───────────── Problem 1: Contains Duplicate ───────────── */

const DUP_CODE = [
  'def contains_duplicate(nums):',
  '    seen = set()',
  '    for x in nums:',
  '        if x in seen:',
  '            return True',
  '        seen.add(x)',
  '    return False',
]

/** The same solution in Java; DUP_JAVA_MAP[k] = Java line for Python line k. */
const DUP_JAVA = [
  'public boolean containsDuplicate(int[] nums) {',
  '    Set<Integer> seen = new HashSet<>();',
  '    for (int x : nums) {',
  '        if (seen.contains(x)) {',
  '            return true;',
  '        }',
  '        seen.add(x);',
  '    }',
  '    return false;',
  '}',
]
const DUP_JAVA_MAP = [0, 1, 2, 3, 4, 6, 8]

/** Runs the real algorithm on `nums` and records one frame per decision. */
function traceDuplicate(nums: number[], board: string[], intro: string): Frame[] {
  const frames: Frame[] = []
  const seen: number[] = []
  const vals = nums.map(String)
  const base = { stage: 6, clock: 'min 22–28', board, fresh: 0, code: DUP_CODE.length }
  const done = (upTo: number) => Object.fromEntries(Array.from({ length: upTo }, (_, k) => [k, 'done' as CellState]))
  const snap = (): [string, string][] => seen.map((v) => [String(v), ''])
  const trace = (i: number, states: Partial<Record<number, CellState>>, extra: Partial<Trace> = {}): Trace => ({
    arrays: [{ caption: 'nums', values: vals, states, pointers: i >= 0 && i < nums.length ? [{ at: i, label: 'x' }] : [] }],
    mapTitle: 'seen',
    map: snap(),
    ...extra,
  })

  frames.push({ ...base, say: intro, line: 1, trace: trace(-1, {}), note: 'Una traza a mano con tu propio ejemplo encuentra la mayoría de los bugs antes que el entrevistador. Vas línea por línea, con los valores reales.' })
  for (let i = 0; i < nums.length; i++) {
    const x = nums[i]
    if (seen.includes(x)) {
      const j = nums.indexOf(x)
      frames.push({
        ...base,
        say: `x = ${x}: ¿está en seen? Sí, ya lo vi en la posición ${j}. Devuelvo True.`,
        line: [3, 4],
        trace: trace(i, { ...done(i), [j]: 'found', [i]: 'found' }, { hit: String(x) }),
        note: `El ${x} aparece dos veces y la función corta en cuanto lo detecta, sin mirar el resto. Coincide con lo que anotaste en los ejemplos.`,
        tone: 'ok',
      })
      return frames
    }
    frames.push({
      ...base,
      say: `x = ${x}: ¿está en seen? No.`,
      line: [2, 3],
      trace: trace(i, { ...done(i), [i]: 'active' }),
      note: `La consulta "x in seen" en un conjunto cuesta O(1) en promedio: es lo que reemplazó la búsqueda O(n) de la fuerza bruta.`,
    })
    seen.push(x)
    frames.push({
      ...base,
      say: `Agrego ${x} a seen.`,
      line: 5,
      trace: trace(i, { ...done(i), [i]: 'active' }, { fresh: String(x) }),
      note: `seen guarda todo lo que ya recorrimos. El invariante: antes de mirar nums[i], seen tiene exactamente nums[0..i−1].`,
    })
  }
  frames.push({
    ...base,
    say: nums.length === 0 ? 'Con la lista vacía el for no entra ni una vez y devuelvo False. Es lo que acordamos.' : 'Terminé el recorrido sin repetidos: devuelvo False.',
    line: 6,
    trace: trace(nums.length, done(nums.length)),
    note: nums.length === 0 ? 'Probar el vacío toma diez segundos y es el caso borde que más se olvida. Aquí el código ya lo cubría sin un if especial.' : 'Ningún valor se repitió: la respuesta es False.',
    tone: 'ok',
  })
  return frames
}

