/* ───────────── Problem 2: Valid Anagram ───────────── */

const ANA_CODE = [
  'def is_anagram(s, t):',
  '    if len(s) != len(t):',
  '        return False',
  '    count = {}',
  '    for c in s:',
  '        count[c] = count.get(c, 0) + 1',
  '    for c in t:',
  '        if count.get(c, 0) == 0:',
  '            return False',
  '        count[c] -= 1',
  '    return True',
]

/** The same solution in Java; ANA_JAVA_MAP[k] = Java line for Python line k. */
const ANA_JAVA = [
  'public boolean isAnagram(String s, String t) {',
  '    if (s.length() != t.length()) {',
  '        return false;',
  '    }',
  '    Map<Character, Integer> count = new HashMap<>();',
  '    for (char c : s.toCharArray()) {',
  '        count.merge(c, 1, Integer::sum);',
  '    }',
  '    for (char c : t.toCharArray()) {',
  '        if (count.getOrDefault(c, 0) == 0) {',
  '            return false;',
  '        }',
  '        count.merge(c, -1, Integer::sum);',
  '    }',
  '    return true;',
  '}',
]
const ANA_JAVA_MAP = [0, 1, 2, 4, 5, 6, 8, 9, 10, 12, 14]

/**
 * Runs the counting algorithm on (s, t). With `compact`, the first loop is
 * shown as a single frame so the edge case goes straight to the interesting part.
 */
function traceAnagram(s: string, t: string, board: string[], intro: string, clock: string, compact = false): Frame[] {
  const frames: Frame[] = []
  const count = new Map<string, number>()
  const base = { stage: 6, clock, board, fresh: 0, code: ANA_CODE.length }
  const S = s.split('')
  const T = t.split('')
  const snap = (): [string, string][] => [...count.entries()].map(([k, v]) => [k, String(v)])
  const done = (upTo: number) => Object.fromEntries(Array.from({ length: upTo }, (_, k) => [k, 'done' as CellState]))
  const trace = (si: number, ti: number, sStates: Partial<Record<number, CellState>>, tStates: Partial<Record<number, CellState>>, extra: Partial<Trace> = {}): Trace => ({
    arrays: [
      { caption: 's', values: S, states: sStates, pointers: si >= 0 && si < S.length ? [{ at: si, label: 'c' }] : [] },
      { caption: 't', values: T, states: tStates, pointers: ti >= 0 && ti < T.length ? [{ at: ti, label: 'c' }] : [] },
    ],
    mapTitle: 'count',
    map: snap(),
    ...extra,
  })

  frames.push({ ...base, say: intro, line: 1, trace: trace(-1, -1, {}, {}), note: s.length === t.length ? `Largo ${s.length} contra ${t.length}: iguales, así que seguimos.` : `Largo ${s.length} contra ${t.length}: distintos.` })
  if (s.length !== t.length) {
    frames.push({ ...base, say: 'Los largos difieren: devuelvo False sin contar nada.', line: 2, trace: trace(-1, -1, {}, {}), note: 'El caso que acordaste al aclarar ya está cubierto por la primera línea.', tone: 'ok' })
    return frames
  }
  for (let i = 0; i < S.length; i++) {
    const c = S[i]
    count.set(c, (count.get(c) ?? 0) + 1)
    if (!compact) {
      frames.push({
        ...base,
        say: `c = '${c}': count['${c}'] pasa a ${count.get(c)}.`,
        line: [4, 5],
        trace: trace(i, -1, { ...done(i), [i]: 'active' }, {}, { fresh: c }),
        note: 'Primera pasada: sumamos cuántas veces aparece cada letra en s. count.get(c, 0) evita el error de leer una clave que aún no existe.',
      })
    }
  }
  if (compact) {
    frames.push({
      ...base,
      say: `Cuento s: ${snap()
        .map(([k, v]) => `${k}=${v}`)
        .join(', ')}.`,
      line: [4, 5],
      trace: trace(S.length, -1, done(S.length), {}),
      note: 'La primera pasada ya la vimos funcionar; aquí lo interesante es la segunda.',
    })
  }
  for (let i = 0; i < T.length; i++) {
    const c = T[i]
    const have = count.get(c) ?? 0
    if (have === 0) {
      frames.push({
        ...base,
        say: `c = '${c}': count['${c}'] es 0. Esta '${c}' sobra en t: devuelvo False.`,
        line: [7, 8],
        trace: trace(S.length, i, done(S.length), { ...done(i), [i]: 'bad' }, { hit: c }),
        note: `Mismas letras, distinta cantidad: t tiene una '${c}' de más. Es justo el ejemplo que rompe a quien compara solo conjuntos de letras.`,
        tone: 'ok',
      })
      return frames
    }
    count.set(c, have - 1)
    frames.push({
      ...base,
      say: `c = '${c}': hay ${have} disponible${have === 1 ? '' : 's'}, la descuento y queda en ${have - 1}.`,
      line: [7, 9],
      trace: trace(S.length, i, done(S.length), { ...done(i), [i]: 'active' }, { fresh: c }),
      note: 'Segunda pasada: cada letra de t consume una de s. Si alguna no encuentra pareja, sobra.',
    })
  }
  frames.push({
    ...base,
    say: 'Ninguna letra faltó: devuelvo True.',
    line: 10,
    trace: trace(S.length, T.length, done(S.length), Object.fromEntries(T.map((_, k) => [k, 'found' as CellState]))),
    note: 'Como los largos son iguales y ninguna letra de t faltó, tampoco puede sobrar ninguna de s: todas las cuentas quedaron en 0.',
    tone: 'ok',
  })
  return frames
}

